style.css:
@-moz-document domain("tiktok.com") {
body {
    background: url("https://files.catbox.moe/ozq9t3.gif") no-repeat center center fixed !important;
    background-size: cover !important;
    color: black !important;
    font-weight: bold !important;
  }

  /* Transparent containers for better GIF visibility */
  .tiktok-1kbyatn-DivBodyContainer,
  .tiktok-11u47i-DivMainContainer,
  .tiktok-1soki6-DivContainer {
    background-color: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(5px) !important;
  }

  /* Optional: hide TikTok watermark */
  .tiktok-1soki6-DivContainer:after {
    display: none !important;
  }
}
